'use strict';
const $=(s,root=document)=>root.querySelector(s);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const dt=d=>new Date(d+'T12:00:00');const deDate=(d,opts={day:'2-digit',month:'short'})=>dt(d).toLocaleDateString('de-DE',opts);
const today=dateKey();
const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',focus:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="4"/><path d="M12 1v3M12 20v3"/>',feather:'<path d="M21 3c-9 1-15 4-17 11-1 4 1 7 5 7 8 0 12-9 12-18Z"/><path d="M3 22c5-7 10-11 17-17M9 17l-1-6M14 12l-1-6"/>',flame:'<path d="M12 22c5 0 8-3 8-8 0-4-2-7-5-10-.4 3-2 4-3 6C11 7 9 5 8 3c0 4-4 7-4 12 0 4 3 7 8 7Z"/><path d="M12 21c2.3 0 4-1.7 4-4 0-1.5-1-3-2-4-1 2-3 3-3 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',chev:'<path d="m9 18 6-6-6-6"/>',left:'<path d="m15 18-6-6 6-6"/>',right:'<path d="m9 18 6-6-6-6"/>',close:'<path d="M18 6 6 18M6 6l12 12"/>',play:'<path d="m8 5 12 7-12 7z"/>',pause:'<path d="M8 5v14M16 5v14"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9ZM10 21h4"/>',book:'<path d="M3 5a2 2 0 0 1 2-2h5a4 4 0 0 1 2 1 4 4 0 0 1 2-1h5a2 2 0 0 1 2 2v14a2 2 0 0 0-2-2h-5a4 4 0 0 0-2 1 4 4 0 0 0-2-1H5a2 2 0 0 0-2 2zM12 4v14"/>',dumbbell:'<path d="M3 9v6M7 7v10M17 7v10M21 9v6M7 12h10M1 9h4M19 9h4"/>',droplet:'<path d="M12 2c-3 4-7 8-7 12a7 7 0 0 0 14 0c0-4-4-8-7-12Z"/>',steps:'<path d="M6 11c-2-2-2-6 0-7 2-1 4 1 4 4 0 2-1 3-4 3ZM6 14c2 1 4 2 3 5S2 22 3 19s1-4 3-5ZM18 11c-2-2-2-6 0-7 2-1 4 1 4 4 0 2-1 3-4 3ZM18 14c2 1 4 2 3 5s-7 3-6 0 1-4 3-5Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',settings:'<path d="M10 3h4l1 2 2 1 2-1 2 4-2 2v2l2 2-2 4-2-1-2 1-1 2h-4l-1-2-2-1-2 1-2-4 2-2v-2L3 9l2-4 2 1 2-1z"/><circle cx="12" cy="12" r="3"/>',share:'<path d="M12 15V3m-4 4 4-4 4 4M5 13v7h14v-7"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4 12H2M22 12h-2M5 5l2 2M17 17l2 2M19 5l-2 2M7 17l-2 2"/>',moon:'<path d="M21 13A9 9 0 0 1 11 3 9 9 0 1 0 21 13Z"/>',wind:'<path d="M3 8h11a3 3 0 1 0-3-3M2 12h18M4 16h10a3 3 0 1 1-3 3"/>',export:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',link:'<path d="M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2"/>',check:'<path d="m4 12 5 5L20 6"/>',edit:'<path d="m16 5 3 3M4 20l4-.7L20 7a2 2 0 0 0-3-3L5 16z"/>',trash:'<path d="M4 7h16M10 4h4M6 7l1 14h10l1-14M10 11v7M14 11v7"/>',copy:'<rect x="7" y="7" width="13" height="14" rx="2"/><path d="M16 7V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h2"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',shield:'<path d="M12 2 21 6v6c0 5-4 8-9 10-5-2-9-5-9-10V6z"/>'};
function icon(key,extra=''){return `<svg class="${extra}" viewBox="0 0 24 24" width="20" height="20" stroke="currentColor" stroke-width="1.7" fill="none" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[key]||paths.focus}</svg>`}
function featherArt(size=55,locked=false){return `<svg viewBox="0 0 82 82" width="${size}" height="${size}" aria-hidden="true"><defs><linearGradient id="fg${size}${locked?1:0}" x1="0" x2="1" y2="1"><stop stop-color="${locked?'#9b939c':'#f0d0b7'}"/><stop offset=".48" stop-color="${locked?'#716b76':'#b6a5d8'}"/><stop offset="1" stop-color="${locked?'#69636b':'#8ac7bd'}"/></linearGradient></defs><path d="M65 9C38 10 17 24 17 48c0 17 12 24 25 18 20-10 23-32 23-57Z" fill="url(#fg${size}${locked?1:0})" opacity=".96"/><path d="M11 70c16-25 31-38 51-54M31 49l-1-20M43 37l-1-17" stroke="#fdf9f7" stroke-width="2.6" fill="none" stroke-linecap="round" opacity=".85"/></svg>`}
const defaultWorkouts=[
{title:'Oberkörper',note:'Kontrolliert und mit Pausen',ex:[{name:'Aufwärmen',sets:'5 Min',reps:'Beweglichkeit'},{name:'Klimmzüge',sets:'2 Sätze',reps:'Saubere Wdh.'},{name:'Liegestütze',sets:'3 Sätze',reps:'8–15 Wdh.'},{name:'Rudern',sets:'2 Sätze',reps:'8–12 Wdh.'},{name:'Dehnen',sets:'5 Min',reps:'Locker'}]},
{title:'Bewegung & Mobilität',note:'Leicht und entspannt',ex:[{name:'Spazieren',sets:'20–30 Min',reps:'Angenehmes Tempo'},{name:'Mobilität',sets:'10 Min',reps:'Schultern & Hüfte'}]},
{title:'Unterkörper',note:'Saubere Technik vor Tempo',ex:[{name:'Aufwärmen',sets:'5 Min',reps:'Locker'},{name:'Kniebeugen',sets:'3 Sätze',reps:'8–12 Wdh.'},{name:'Ausfallschritte',sets:'2 Sätze',reps:'8 je Seite'},{name:'Glute Bridge',sets:'2 Sätze',reps:'12 Wdh.'}]},
{title:'Erholung',note:'Ein ruhiger Tag ist Teil des Plans',ex:[{name:'Lockere Bewegung',sets:'Optional',reps:'Nach Gefühl'}]},
{title:'Ganzkörper',note:'Gleichmäßiges Tempo',ex:[{name:'Aufwärmen',sets:'5 Min',reps:'Locker'},{name:'Liegestütze',sets:'2 Sätze',reps:'8–12 Wdh.'},{name:'Kniebeugen',sets:'2 Sätze',reps:'10 Wdh.'},{name:'Rudern',sets:'2 Sätze',reps:'8–12 Wdh.'}]},
{title:'Freie Aktivität',note:'Eine Aktivität, die dir Spaß macht',ex:[{name:'Bewegung nach Wahl',sets:'Optional',reps:'Ohne Leistungsdruck'}]},
{title:'Ruhetag',note:'Erholung und Wochenplanung',ex:[]}
];
const defaults={name:'',goals:['Gesund bleiben','Trainierter Körper','Mehr Zeit für wichtige Dinge'],events:[],video:'',videoTitle:'Mein Motivationsvideo',steps:{},water:{},waterGlass:250,stepGoal:10000,routines:{morning:['Wasser trinken','Tagesziele ansehen','Kurz bewegen'],evening:['Für morgen vorbereiten','Handy zur Seite legen','Zur Ruhe kommen']},routineChecks:{},workouts:defaultWorkouts,focusLog:{},streakDays:[],settings:{morning:'06:00',evening:'21:30',blink:30,appMinutes:10,appName:'TikTok',quote:'',normalInterval:30,quote:''},shieldContents:{morning:{goals:true,reminders:false,steps:false,video:false,quote:false},evening:{goals:true,reminders:false,steps:false,video:false,quote:false},normal:{goals:true,reminders:false,steps:true,video:false,quote:false}},onboarded:false};
let state=load();let ui={tab:'home',goalIndex:0,routine:'morning',planDay:(new Date().getDay()+6)%7,selectedDate:today,calDate:dt(today),focusMode:'normal',focusMinutes:25,shield:null,activeFocus:null,breathLeft:3};let intervalTimer=null;let toastTimer;
function load(){let saved={};try{saved=JSON.parse(localStorage.getItem('klar_private_v1')||'{}')||{}}catch(_){}return {...defaults,...saved,settings:{...defaults.settings,...(saved.settings||{})},shieldContents:{...defaults.shieldContents,...(saved.shieldContents||{})},routines:{...defaults.routines,...(saved.routines||{})},workouts:Array.isArray(saved.workouts)&&saved.workouts.length===7?saved.workouts:structuredCloneSafe(defaultWorkouts)}}
function structuredCloneSafe(x){return JSON.parse(JSON.stringify(x))}function save(){try{localStorage.setItem('klar_private_v1',JSON.stringify(state))}catch(_){toast('Speichern nicht möglich: Gerätespeicher prüfen.')}}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3000)}
function uid(){return Math.random().toString(36).slice(2)+Date.now().toString(36)}
function head(){ $('#headmark').innerHTML=featherArt(34);$('#profileInitial').textContent=(state.name||'K').trim().charAt(0).toUpperCase();$('#dateButton').textContent=deDate(ui.selectedDate,{weekday:'short',day:'numeric',month:'short'})+' ⌄';$('#headerFlame').innerHTML=icon('flame');document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('selected',t.dataset.tab===ui.tab));document.querySelectorAll('[data-icon]').forEach(x=>x.innerHTML=icon(x.dataset.icon));}
function render(){head();let html={home:homeView,plan:planView,focus:focusView,progress:progressView}[ui.tab]();$('#main').innerHTML=html;$('#calendarPop').classList.add('hidden');$('#profilePop').classList.add('hidden')}
function section(title,action='',content=''){return `<section class="section"><div class="section-head"><h2>${title}</h2>${action}</div>${content}</section>`}
function todayEvents(){return state.events.filter(e=>e.date===today).sort((a,b)=>(a.time||'').localeCompare(b.time||''))}
function homeView(){let g=state.goals[ui.goalIndex]||'';let ev=todayEvents();let checks=state.routineChecks[today]?.[ui.routine]||[];let tasks=state.routines[ui.routine];return `<div class="eyebrow" style="margin-top:13px">Deine Richtung</div><div class="page-title">${state.name?'Dein Tag, '+esc(state.name)+'.':'Dein Tag. Deine Ziele.'}</div><p class="page-sub">Was dir wichtig ist, bleibt hier sichtbar.</p>
<div class="panel goal-hero"><div class="goal-index">ZIEL ${Math.min(ui.goalIndex+1,state.goals.length)} / ${state.goals.length}</div><div class="goal-switch"><button data-action="prevGoal" aria-label="Vorheriges Ziel">${icon('left')}</button><button data-action="nextGoal" aria-label="Nächstes Ziel">${icon('right')}</button></div><h2>${esc(g)}</h2><div class="goal-foot"><span>Deine persönlichen Ziele</span><span class="goal-track">${state.goals.map((_,i)=>`<i class="${i===ui.goalIndex?'on':''}"></i>`).join('')}</span></div></div><div style="text-align:right;margin:6px 2px 0"><button class="text-button" data-action="goals">Ziele bearbeiten ${icon('chev')}</button></div>
${ev.length?section('Erinnerungen für heute',`<button class="text-button" data-action="addEvent">Hinzufügen ${icon('plus')}</button>`,`<div class="reminders">${ev.map(e=>`<div class="reminder-row"><span class="event-mark">${icon(e.type==='Klausur'?'book':e.type==='Training'?'dumbbell':'bell')}</span><span style="flex:1"><strong>${esc(e.title)}</strong><small>${esc(e.type)}${e.note?' · '+esc(e.note):''}</small></span><span class="right">${esc(e.time||'Ganztägig')}</span></div>`).join('')}</div>`):''}
${section('Dein Video',`<button class="text-button" data-action="video">${state.video?'Ändern':'Hinzufügen'} ${icon('chev')}</button>`,`<div class="panel video-card"><div class="video-art">${icon('play')}</div><div class="video-body"><div class="eyebrow">${state.video?'Gespeichert':'Deine persönliche Auswahl'}</div><strong>${esc(state.video?state.videoTitle:'Ein Video für deinen Fokus')}</strong><div class="inline-actions"><button class="quiet-button primary" data-action="${state.video?'playVideo':'video'}">${state.video?'Abspielen':'Link hinzufügen'}</button></div></div></div>`)}
${section('Routinen',`<button class="text-button" data-action="routines">Bearbeiten ${icon('chev')}</button>`,`<div class="subtabs"><button class="${ui.routine==='morning'?'active':''}" data-routine="morning">Morgen</button><button class="${ui.routine==='evening'?'active':''}" data-routine="evening">Abend</button></div><div class="panel" style="margin-top:10px"><div class="routine-list">${tasks.map((r,i)=>`<label class="routine-row"><input class="check" type="checkbox" data-routinecheck="${i}" ${checks.includes(i)?'checked':''}><span class="${checks.includes(i)?'routine-done':''}">${esc(r)}</span></label>`).join('')||'<div class="empty">Noch keine Schritte in dieser Routine.</div>'}</div><div class="routine-bottom"><span class="routine-meta">${checks.length} / ${tasks.length} erledigt · ${ui.routine==='morning'?state.settings.morning:state.settings.evening}</span><button class="text-button" data-action="previewRoutine">Vorschau ${icon('chev')}</button></div></div>`)}
${section('Deine Schritte',`<button class="text-button" data-tab="plan">Im Plan ${icon('chev')}</button>`,`<div class="panel small-data"><div><div class="micro-label">Heute · Apple Health über Kurzbefehl</div><div class="big">${state.steps[today]!==undefined?Number(state.steps[today]).toLocaleString('de-DE'):'—'} <span class="muted" style="font-size:12px;font-weight:400">/ ${state.stepGoal.toLocaleString('de-DE')}</span></div><div class="tinybar" style="width:170px"><span style="width:${Math.min(100,(state.steps[today]||0)/state.stepGoal*100)}%"></span></div></div><button class="quiet-button" data-action="stepImport">Aktualisieren</button></div>`)}
`}
function planView(){let i=ui.planDay,w=state.workouts[i];let d=new Date();d.setDate(d.getDate()+i-(d.getDay()+6)%7);let schedule=state.events.filter(e=>e.date===ui.selectedDate).sort((a,b)=>(a.time||'').localeCompare(b.time||''));return `<div class="page-title">Dein Plan</div><p class="page-sub">Training, Schule, Termine und Aktivität.</p>
<div class="panel small-data"><div><div class="eyebrow">Ausgewählter Tag</div><strong style="font-size:17px">${deDate(ui.selectedDate,{weekday:'long',day:'numeric',month:'long'})}</strong></div><button class="quiet-button" data-action="datePick">${icon('calendar')} Kalender</button></div>
${section('Training von Montag bis Sonntag',`<button class="text-button" data-action="editWorkout">Bearbeiten ${icon('edit')}</button>`,`<div class="split-day-strip">${['Mo','Di','Mi','Do','Fr','Sa','So'].map((n,k)=>`<button class="${k===i?'selected':''}" data-day="${k}"><span>${n}</span><strong>${String(k+1).padStart(2,'0')}</strong></button>`).join('')}</div><div class="panel split-banner"><div class="eyebrow">${['Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag','Sonntag'][i]}</div><h2>${esc(w.title)}</h2><div class="micro-label">${esc(w.note)}</div></div><div class="panel" style="margin-top:9px">${w.ex.length?w.ex.map((x,k)=>`<div class="exercise-row"><div class="number-badge">${k+1}</div><div><strong>${esc(x.name)}</strong><small>${esc(x.reps)}</small></div><div class="sets">${esc(x.sets)}</div></div>`).join(''):'<div class="empty">Heute ist kein Training eingeplant.</div>'}<div style="padding:12px 14px"><button class="text-button" data-action="addExercise">${icon('plus')} Übung hinzufügen</button></div></div>`)}
${section('Klausuren & Termine',`<button class="text-button" data-action="addEvent">${icon('plus')} Eintragen</button>`,`${schedule.length?`<div class="panel">${schedule.map(e=>`<div class="event-row"><span class="event-mark">${icon(e.type==='Klausur'?'book':e.type==='Training'?'dumbbell':'calendar')}</span><div class="desc"><div class="event-type">${esc(e.type)}</div><strong>${esc(e.title)}</strong><small>${esc(e.time||'Ganztägig')}${e.note?' · '+esc(e.note):''}</small></div><button class="text-button" data-action="eventActions" data-id="${esc(e.id)}">${icon('more')}</button></div>`).join('')}</div>`:'<div class="empty">Für dieses Datum ist noch nichts eingetragen.</div>'}`)}
${section('Schritte & Wasser',`<button class="text-button" data-action="stepImport">Schritte abrufen ${icon('chev')}</button>`,`<div class="panel" style="padding:16px"><div class="button-row"><div><div class="eyebrow" style="color:var(--mint)">Schritte</div><div class="progress-big" style="font-size:27px">${state.steps[ui.selectedDate]!==undefined?Number(state.steps[ui.selectedDate]).toLocaleString('de-DE'):'—'}</div><div class="micro-label">Heute automatisch über Kurzbefehle übertragbar</div></div><div><div class="eyebrow" style="color:#aabbdc">Wasser</div><div class="progress-big" style="font-size:27px">${((state.water[ui.selectedDate]||0)/1000).toLocaleString('de-DE',{maximumFractionDigits:2})} L</div><div class="micro-label">Bisher eingetragen</div></div></div><div class="button-row" style="margin-top:15px"><button class="quiet-button primary" data-action="addWater">${icon('droplet')} + ${state.waterGlass} ml</button><button class="quiet-button" data-action="waterSettings">Wassermenge ändern</button></div></div>${chart('Schritte · letzte 7 Tage',state.steps,'mint')}`)}
`}
function focusView(){return `<div class="page-title">Fokus</div><p class="page-sub">Eine bewusste Unterbrechung. Deine Zeit.</p><div class="panel focus-card"><div class="breath-orb">${icon('focus')}</div><div class="eyebrow">Jetzt beginnen</div><h2>Dein Fokusmoment</h2><p>Beim Start öffnen sich direkt deine Ziele und die Atempause.</p><label class="field" style="text-align:left"><span>Dauer: <strong id="focusLabel">${ui.focusMinutes} Minuten</strong></span><input id="focusDuration" type="range" min="5" max="180" step="5" value="${ui.focusMinutes}"></label><button class="btn" style="width:100%" data-action="startFocus">Fokus starten ${icon('right')}</button></div>
${section('Deine drei Ansichten','',`<div class="focus-mode-tabs">${[['morning','Morgen'],['evening','Abend'],['normal','Pause']].map(([k,v])=>`<button data-focusmode="${k}" class="${ui.focusMode===k?'selected':''}">${v}</button>`).join('')}</div><div class="panel shield-card"><div class="eyebrow">${ui.focusMode==='morning'?'Morgenroutine':ui.focusMode==='evening'?'Abendroutine':'Normale Pause'}</div><h2 style="font-size:20px;margin:9px 0 5px">${ui.focusMode==='morning'?'Start in deinen Tag':ui.focusMode==='evening'?'Den Tag abschließen':'Kurz innehalten'}</h2><div class="shield-goals">${state.goals.map(g=>`<span>${esc(g)}</span>`).join('')}</div><div class="micro-label">${ui.focusMode==='normal'?'3 Sekunden ausatmen':ui.focusMode==='morning'?'Checkliste '+esc(state.settings.morning):'Checkliste '+esc(state.settings.evening)}</div><button class="btn ghost" style="width:100%;margin-top:14px" data-action="showShield">Ansicht öffnen</button></div>`)}
${section('Automationen',`<button class="text-button" data-action="shortcuts">Einrichten ${icon('chev')}</button>`,`<div class="panel settings-group"><div class="setting-line"><div><strong>Beim Öffnen von ${esc(state.settings.appName)} reagieren</strong><small>Automatischer Kurzbefehl für die App</small></div>${icon('chev')}</div><div class="setting-line"><div><strong>Alle ${state.settings.normalInterval} Minuten erinnern</strong><small>In Apples Kurzbefehle / Erinnerungen einrichten</small></div>${icon('bell')}</div><div class="setting-line"><div><strong>Morgen ${esc(state.settings.morning)} · Abend ${esc(state.settings.evening)}</strong><small>Getrennte Ansichten und Routinen</small></div>${icon('clock')}</div><div class="setting-line"><div><strong>Blinzelpause alle ${state.settings.blink} Minuten</strong><small>Hinweis über Apple-Erinnerungen</small></div>${icon('eye')}</div></div>`)}
`}
function streakCount(){let count=0,d=new Date();if(!state.streakDays.includes(dateKey(d)))d.setDate(d.getDate()-1);while(state.streakDays.includes(dateKey(d))){count++;d.setDate(d.getDate()-1)}return count}
function streakActive(){if(!state.streakDays.includes(today)){state.streakDays.push(today);save()}}
function sevenKeys(){return Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-(6-i));return dateKey(d)})}
function chart(title,obj,kind='mint'){let days=sevenKeys(),mx=Math.max(1,...days.map(k=>Number(obj[k]||0)));return `<div class="panel graph"><div class="section-head"><h2 style="font-size:14px">${title}</h2></div><div class="bar-chart">${days.map(k=>{let v=Number(obj[k]||0),h=Math.max(v?12:3,v/mx*91);return `<div class="bar-item ${kind==='violet'?'violet':''}" title="${esc(deDate(k))}: ${v}"><div class="bar" style="height:${h}%"></div><small>${deDate(k,{weekday:'short'}).slice(0,2)}</small></div>`}).join('')}</div></div>`}
function progressView(){let count=streakCount(),focusTotal=Object.values(state.focusLog).reduce((a,b)=>a+Number(b||0),0);let weeklyStep=sevenKeys().reduce((a,k)=>a+Number(state.steps[k]||0),0);let badges=[{days:3,title:'Erster Anfang'},{days:7,title:'Eine Woche'},{days:14,title:'Dranbleiben'},{days:30,title:'Konstanz'},{days:60,title:'Klarheit'},{days:100,title:'Meilenstein'}];return `<div class="page-title">Deine Erfolge</div><p class="page-sub">Keine erfundenen Statistiken – nur deine Einträge.</p><div class="panel" style="padding:21px;display:flex;gap:15px;align-items:center;background:linear-gradient(110deg,#37303a,#252630)"><div style="flex:1"><div class="eyebrow">Aktuelle Serie</div><div class="progress-big" style="margin:9px 0">${count} ${count===1?'Tag':'Tage'}</div><div class="micro-label">Ein aktiver Tag zählt, wenn du eine Routine oder einen Fokusmoment abschließt.</div></div>${featherArt(91)}</div>
${section('Deine Federn','',`<div class="badges">${badges.map(b=>`<div class="badge-card ${count<b.days?'locked':''}">${featherArt(48,count<b.days)}<strong>${esc(b.title)}</strong><small>${b.days} Tage</small></div>`).join('')}</div>`)}
${section('Aktivität','',`<div class="panel small-data"><div><div class="eyebrow">Schritte · 7 Tage</div><div class="big">${weeklyStep.toLocaleString('de-DE')}</div></div><div><div class="eyebrow">Fokus gesamt</div><div class="big">${focusTotal} min</div></div></div>${chart('Schritte · Wochenverlauf',state.steps,'mint')}${chart('Fokus · Minuten pro Tag',state.focusLog,'violet')}`)}
${section('Freunde einladen','',`<div class="panel" style="padding:17px;display:flex;align-items:center;gap:12px">${featherArt(58,true)}<div style="flex:1"><strong>Besondere Feder</strong><p class="micro-label" style="margin:5px 0">Die Einladung lässt sich teilen. Eine automatische Zählung der Einladungen ist noch nicht vorhanden.</p></div><button class="quiet-button" data-action="share">${icon('share')}</button></div>`)}
`}
function openModal(title,body){$('#modalHost').innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="x-button" data-action="closeModal" aria-label="Schließen">${icon('close')}</button></div>${body}</div></div>`}
function closeModal(){$('#modalHost').innerHTML=''}
function goalsModal(){openModal('Deine Ziele',`<p>Ohne Prozentwerte und Symbolauswahl. Die Ziele erscheinen ganz oben auf deiner Übersicht und bei deinen Fokus-Pausen.</p><form id="goalsForm">${state.goals.map((g,i)=>`<label class="field"><span>Ziel ${i+1}</span><input name="goal${i}" maxlength="90" required value="${esc(g)}"></label>`).join('')}<label class="field"><span>Weiteres Ziel (optional)</span><input name="newGoal" maxlength="90" placeholder="Ein weiteres persönliches Ziel"></label><button class="btn" type="submit">Ziele speichern</button></form><button class="text-button" data-action="removeGoal">Letztes Ziel entfernen</button>`)}
function eventModal(){openModal('Termin oder Klausur',`<form id="eventForm"><label class="field"><span>Titel</span><input name="title" maxlength="100" placeholder="z. B. Matheklausur" required></label><label class="field"><span>Art</span><select name="type"><option>Termin</option><option>Klausur</option><option>Erinnerung</option><option>Training</option></select></label><div class="button-row"><label class="field"><span>Datum</span><input type="date" name="date" value="${ui.selectedDate}" required></label><label class="field"><span>Uhrzeit</span><input type="time" name="time" value="16:00"></label></div><label class="field"><span>Notiz (optional)</span><input name="note" maxlength="200" placeholder="Raum, Thema oder Vorbereitung"></label><button class="btn" type="submit">Eintragen</button></form><p>Für eine iPhone-Benachrichtigung kannst du den Termin anschließend in Apple Kalender übernehmen.</p>`)}
function eventActions(id){let e=state.events.find(x=>x.id===id);if(!e)return;openModal('Eintrag',`<strong>${esc(e.title)}</strong><p>${deDate(e.date)} · ${esc(e.time||'Ganztägig')}</p><div class="button-row"><button class="btn ghost" data-action="exportIcs" data-id="${esc(id)}">Kalenderdatei</button><button class="btn destructive" data-action="deleteEvent" data-id="${esc(id)}">Löschen</button></div><p>Die Kalenderdatei enthält eine Erinnerung 15 Minuten vor dem Termin. Bestätige den Import in Apples Kalender.</p>`)}
function videoModal(){openModal('Dein Motivationsvideo',`<p>Füge einen YouTube-, Vimeo- oder direkten Videolink ein. Der Link bleibt lokal auf deinem Gerät gespeichert.</p><form id="videoForm"><label class="field"><span>Titel</span><input name="title" maxlength="90" value="${esc(state.videoTitle)}"></label><label class="field"><span>Video-Link</span><input name="url" type="url" placeholder="https://..." value="${esc(state.video)}"></label><button class="btn" type="submit">Video speichern</button></form>${state.video?'<button class="text-button" data-action="removeVideo">Video entfernen</button>':''}`)}
function parseVideoURL(str){let u;try{u=new URL(str)}catch(_){return null}if(u.protocol!=='https:'&&u.protocol!=='http:')return null;const h=u.hostname.toLowerCase();let id;if(['www.youtube.com','youtube.com','m.youtube.com','music.youtube.com','youtube-nocookie.com','www.youtube-nocookie.com'].includes(h)){id=u.searchParams.get('v')||u.pathname.split('/').filter(Boolean).pop();if(u.pathname.startsWith('/watch')&&!u.searchParams.get('v'))id=null; if(u.pathname.startsWith('/embed/')||u.pathname.startsWith('/shorts/')||u.pathname.startsWith('/live/'))id=u.pathname.split('/')[2];if(id&&/^[\w-]{11}$/.test(id))return {embed:`https://www.youtube-nocookie.com/embed/${id}?rel=0`,open:`https://www.youtube.com/watch?v=${id}`}}if(h==='youtu.be'){id=u.pathname.slice(1);if(/^[\w-]{11}$/.test(id))return {embed:`https://www.youtube-nocookie.com/embed/${id}`,open:u.href}}if(h==='vimeo.com'||h==='www.vimeo.com'){id=u.pathname.split('/').filter(Boolean)[0];if(/^\d+$/.test(id))return {embed:`https://player.vimeo.com/video/${id}`,open:u.href}}if(/\.(mp4|webm|mov)(\?|$)/i.test(u.pathname+u.search))return {direct:u.href,open:u.href};return {open:u.href}}
function playVideo(){let v=parseVideoURL(state.video);if(!v){toast('Bitte zuerst gültigen Videolink hinzufügen.');return}openModal('Video ansehen',`<div style="border-radius:16px;overflow:hidden;background:#090a0b;aspect-ratio:16/9;display:grid;place-items:center">${v.embed?`<iframe src="${esc(v.embed)}" allow="autoplay;encrypted-media;picture-in-picture" allowfullscreen title="Motivationsvideo" style="width:100%;height:100%;border:0"></iframe>`:v.direct?`<video src="${esc(v.direct)}" controls playsinline style="width:100%;max-height:260px"></video>`:`<p>Dieser Link kann nicht direkt eingebettet werden.</p>`}</div><p>Videos benötigen eine Internetverbindung. Manche Anbieter verhindern das Einbetten.</p><a class="quiet-button" style="display:inline-block;text-decoration:none" href="${esc(v.open)}" target="_blank" rel="noopener noreferrer">Extern öffnen ${icon('link')}</a>`)}
function routinesModal(){openModal('Morgen- und Abendroutine',`<p>Hier legst du fest, welche Aufgaben dir morgens und abends angezeigt werden. Die Uhrzeiten stellst du ebenfalls selbst ein.</p><form id="routinesForm"><label class="field"><span>Morgenzeit</span><input type="time" name="morningTime" value="${esc(state.settings.morning)}"></label><label class="field"><span>Morgenschritte – eine Zeile pro Aufgabe</span><textarea name="morning" rows="4">${esc(state.routines.morning.join('\n'))}</textarea></label><label class="field"><span>Abendzeit</span><input type="time" name="eveningTime" value="${esc(state.settings.evening)}"></label><label class="field"><span>Abendschritte – eine Zeile pro Aufgabe</span><textarea name="evening" rows="4">${esc(state.routines.evening.join('\n'))}</textarea></label><button type="submit" class="btn">Routinen speichern</button></form>`)}
function workoutModal(add=false){let w=state.workouts[ui.planDay];if(add){openModal('Übung hinzufügen',`<form id="exerciseForm"><label class="field"><span>Übung</span><input required name="name" placeholder="z. B. Rudern"></label><label class="field"><span>Sätze / Dauer</span><input required name="sets" placeholder="3 Sätze"></label><label class="field"><span>Wiederholungen / Hinweis</span><input name="reps" placeholder="8–12 Wiederholungen"></label><button class="btn" type="submit">Hinzufügen</button></form>`);return}openModal('Training bearbeiten',`<form id="workoutForm"><label class="field"><span>Tagestitel</span><input name="title" required value="${esc(w.title)}"></label><label class="field"><span>Hinweis</span><input name="note" value="${esc(w.note)}"></label><label class="field"><span>Übungen – eine Zeile pro Übung, Format: Name | Sätze | Wiederholungen</span><textarea name="ex" rows="10">${esc(w.ex.map(x=>[x.name,x.sets,x.reps].join(' | ')).join('\n'))}</textarea></label><button class="btn" type="submit">Training speichern</button></form>`)}
function stepModal(){openModal('Apple Health · Schritte',`<p>KLAR ist eine private Web-App. Über <b>Apple Kurzbefehle</b> kannst du Health-Schritte auslesen und an KLAR übergeben. Ein automatischer Hintergrundzugriff ist hier nicht vorhanden.</p><div class="step-box"><b>Kurzbefehle einmal einrichten:</b><br>1. Neuer Kurzbefehl „KLAR Schritte“.<br>2. Aktion „Health-Proben suchen“ / „Gesundheitsdaten suchen“: Typ Schritte, Startdatum Heute.<br>3. Werte summieren (Statistik „Summe“).<br>4. Aktion „In Zwischenablage kopieren“ mit der Summe.<br>5. In KLAR „Aus Zwischenablage“ antippen.</div><div class="button-row"><button class="btn ghost" data-action="launchHealthShortcut">Kurzbefehle öffnen</button><button class="btn" data-action="pasteSteps">Aus Zwischenablage</button></div><form id="stepsForm"><label class="field"><span>Oder Schritte manuell eintragen</span><input name="steps" type="number" min="0" max="200000" value="${state.steps[ui.selectedDate]??''}" placeholder="Heute erfasste Schritte"></label><button type="submit" class="btn ghost">Eintrag speichern</button></form><p>Der Wert ist eine Momentaufnahme. Für neue Schritte aktualisierst du ihn erneut.</p>`)}
function settingsModal(){openModal('Einstellungen',`<form id="settingsForm"><label class="field"><span>Dein Name</span><input name="name" maxlength="30" value="${esc(state.name)}" placeholder="Optional"></label><label class="field"><span>Schrittziel (nur zur Orientierung)</span><input name="stepGoal" type="number" min="100" max="50000" value="${state.stepGoal}"></label><label class="field"><span>Wasser pro Knopfdruck (ml)</span><input name="waterGlass" type="number" min="50" max="1000" step="50" value="${state.waterGlass}"></label><label class="field"><span>Kurzbefehl: App</span><input name="appName" maxlength="40" value="${esc(state.settings.appName)}"></label><label class="field"><span>Nach wie vielen Minuten zum Home-Bildschirm? (Testwert)</span><input name="appMinutes" type="number" min="1" max="120" value="${state.settings.appMinutes}"></label><label class="field"><span>Normale Fokus-Erinnerung alle (Minuten)</span><select name="normalInterval">${[15,30,45,60,90,120].map(x=>`<option value="${x}" ${state.settings.normalInterval===x?'selected':''}>${x} Minuten</option>`).join('')}</select></label><label class="field"><span>Blinzel-Erinnerung alle (Minuten)</span><select name="blink">${[15,20,30,45,60].map(x=>`<option value="${x}" ${state.settings.blink===x?'selected':''}>${x} Minuten</option>`).join('')}</select></label><label class="field"><span>Eigenes Zitat für die Vorschauen (optional)</span><input name="quote" maxlength="150" value="${esc(state.settings.quote||'')}" placeholder="Kein Zitat ausgewählt"></label>${[['morning','Morgen'],['evening','Abend'],['normal','Pause']].map(([mode,label])=>`<div style="margin:14px 0;border-top:1px solid #ffffff15;padding-top:9px"><div class="eyebrow">${label}-Ansicht</div>${[['goals','Ziele'],['reminders','Erinnerungen'],['steps','Schritte'],['video','Video'],['quote','Zitat']].map(([k,n])=>`<label style="display:inline-flex;align-items:center;gap:6px;margin:9px 11px 0 0;font-size:12px;color:#ddd"><input type="checkbox" name="shield_${mode}_${k}" ${state.shieldContents[mode]?.[k]?'checked':''}>${n}</label>`).join('')}</div>`).join('')}<button class="btn" type="submit">Einstellungen speichern</button></form><div style="margin-top:16px"><button class="text-button" data-action="shortcuts">Kurzbefehle-Anleitung</button><br><button class="text-button" data-action="backup">Datensicherung herunterladen</button><br><button class="text-button" data-action="restore">Datensicherung importieren</button><br><button class="text-button" data-action="aboutPrivacy">Datenschutz & Privatnutzung</button></div>`)}
function shortcutsModal(){const m=Number(state.settings.appMinutes);openModal('KLAR mit Kurzbefehle verbinden',`<div class="eyebrow">TikTok und andere Apps</div><p>Du kannst nach einer selbst gewählten Zeit automatisch zum Home-Bildschirm zurückkehren. <b>Das ist keine echte App-Sperre</b>. Längeres „Warten“ läuft auf iOS im Hintergrund oft nicht zuverlässig.</p><div class="step-box"><b>Automation für ${esc(state.settings.appName)}:</b><br>1. Kurzbefehle → Automation → + → „App“.<br>2. App „${esc(state.settings.appName)}“ wählen → „Wird geöffnet“ → „Sofort ausführen“.<br>3. Neue leere Automation → Aktion „Warten“ → <b>${m*60} Sekunden</b> einstellen.<br>4. Danach Aktion „Zum Home-Bildschirm“ hinzufügen.<br>5. Speichern und erst mit einer kurzen Wartezeit testen.<br><span class="muted">Bei ${m} Minuten kann iOS die Warteschleife beenden. Für längere Zeitlimits besser die eingebaute Bildschirmzeit verwenden.</span></div><div class="eyebrow" style="margin-top:20px">Morgen und Abend</div><div class="step-box">Lege zusätzlich zwei Automationen mit dem Auslöser „Tageszeit“ an: <b>${esc(state.settings.morning)}</b> für Morgen, <b>${esc(state.settings.evening)}</b> für Abend. Als Aktion „Mitteilung anzeigen“ oder „URL öffnen“ mit deiner KLAR-Adresse. Dieselbe Methode kannst du für Pausenmeldungen einsetzen.</div><div class="eyebrow" style="margin-top:20px">Schritte aus Health</div><div class="step-box">Erstelle den Kurzbefehl „KLAR Schritte“ mit „Health-Proben suchen“, „Summe berechnen“ und „In Zwischenablage kopieren“. Danach überträgst du die Summe in KLAR mit einem weiteren Tipp.</div><div class="button-row"><button class="btn ghost" data-action="openShortcuts">Kurzbefehle öffnen</button><button class="btn" data-action="exportRoutines">Routinen exportieren</button></div><div class="button-row" style="margin-top:9px"><button class="btn ghost" data-action="exportPause">Fokuspausen exportieren</button><button class="btn ghost" data-action="exportBlink">Blinzelpausen exportieren</button></div><p>Die Pausendateien erzeugen viele tägliche Kalendereinträge zwischen 9 und 20 Uhr. Importiere sie nur, wenn du das möchtest.</p><p>Exportierte Kalenderdateien müssen in Apple Kalender importiert und aktiviert werden. Das sind keine direkt von KLAR zugestellten Push-Mitteilungen.</p>`)}
function aboutPrivacy(){openModal('Datenschutz · Privatnutzung',`<p>KLAR speichert deine Ziele, Termine, Schritte, Routinen und Einstellungen aktuell nur im lokalen Speicher dieses Browsers beziehungsweise dieser installierten Web-App.</p><div class="step-box">Es gibt <b>keinen Server für deine Daten</b>, kein Tracking, keinen Online-Login und keinen Cookie-Banner. Bei Entfernung der App oder Löschung von Websitedaten können deine Einträge verloren gehen. Nutze die Datensicherung.</div><p>Videoplattformen wie YouTube oder Vimeo laden beim Abspielen Inhalte von ihren eigenen Servern; dabei gelten die Datenschutzinformationen des Anbieters.</p><p>Die veröffentlichte statische Programmdatei kann bei kostenlosem Hosting öffentlich erreichbar sein, <b>deine persönlichen gespeicherten Daten liegen aber nicht im hochgeladenen Programmcode</b>.</p><button class="btn ghost" data-action="backup">Datensicherung erstellen</button>`)}
function openProfile(){const p=$('#profilePop');p.classList.toggle('hidden');$('#calendarPop').classList.add('hidden');p.innerHTML=`<button class="popup-item" data-action="settings">${icon('settings')} Einstellungen</button><button class="popup-item" data-action="share">${icon('share')} Freunde einladen</button>`}
function showCalendar(){let p=$('#calendarPop');p.classList.toggle('hidden');$('#profilePop').classList.add('hidden');if(p.classList.contains('hidden'))return;let y=ui.calDate.getFullYear(),m=ui.calDate.getMonth(),start=(new Date(y,m,1).getDay()+6)%7,days=new Date(y,m+1,0).getDate();p.innerHTML=`<div class="mini-cal-head"><button class="text-button" data-action="calPrev">${icon('left')}</button><strong>${new Date(y,m,1).toLocaleDateString('de-DE',{month:'long',year:'numeric'})}</strong><button class="text-button" data-action="calNext">${icon('right')}</button></div><div class="mini-week">${['Mo','Di','Mi','Do','Fr','Sa','So'].map(x=>`<span>${x}</span>`).join('')}</div><div class="mini-days">${'<span></span>'.repeat(start)}${Array.from({length:days},(_,i)=>{let key=`${y}-${String(m+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`;return `<button data-date="${key}" class="${key===ui.selectedDate?'active':''} ${key===today?'today':''}">${i+1}</button>`}).join('')}</div>`}
function icsEsc(x){return String(x??'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;')}
function icsUTC(d){return d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}
function icsEvent(name,date,time,note='',recur=false){let start=new Date(date+'T'+(time||'09:00')+':00');if(!Number.isFinite(+start))return '';let end=new Date(start.getTime()+30*60000);return `BEGIN:VEVENT\r\nUID:${uid()}@klar.privat\r\nDTSTAMP:${icsUTC(new Date())}\r\nDTSTART:${icsUTC(start)}\r\nDTEND:${icsUTC(end)}\r\nSUMMARY:${icsEsc(name)}\r\nDESCRIPTION:${icsEsc(note)}\r\n${recur?'RRULE:FREQ=DAILY\r\n':''}BEGIN:VALARM\r\nTRIGGER:-PT15M\r\nACTION:DISPLAY\r\nDESCRIPTION:${icsEsc(name)}\r\nEND:VALARM\r\nEND:VEVENT\r\n`}
function exportICS(events,filename='KLAR_Termine.ics'){let body=`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//KLAR Privat//DE\r\nCALSCALE:GREGORIAN\r\nMETHOD:PUBLISH\r\n${events}END:VCALENDAR\r\n`;download(filename,body,'text/calendar;charset=utf-8')}
function download(filename,body,type){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([body],{type}));a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),20000)}
function exportEvent(id){let e=state.events.find(x=>x.id===id);if(!e)return;exportICS(icsEvent(e.title,e.date,e.time,e.note),`KLAR_${e.date}.ics`);toast('Kalenderdatei erstellt. In Apple Kalender importieren.')}
function exportPauses(kind){let minutes=Number(kind==='blink'?state.settings.blink:state.settings.normalInterval);let text=kind==='blink'?'KLAR · Augenpause':'KLAR · Kurze Fokuspause';let events='';for(let x=9*60;x<=20*60;x+=minutes){let h=String(Math.floor(x/60)).padStart(2,'0'),m=String(x%60).padStart(2,'0');events+=icsEvent(text,today,h+':'+m,kind==='blink'?'Blick kurz in die Ferne und bewusst blinzeln':'Kurz auf deine Ziele schauen',true)}exportICS(events,kind==='blink'?'KLAR_Augenpausen.ics':'KLAR_Fokuspausen.ics');toast('Kalenderdatei erstellt: tägliche Einträge von 9 bis 20 Uhr.')}
function exportRoutines(){let list=icsEvent('KLAR · Morgenroutine',today,state.settings.morning,'Morgenroutine in KLAR öffnen',true)+icsEvent('KLAR · Abendroutine',today,state.settings.evening,'Abendroutine in KLAR öffnen',true);exportICS(list,'KLAR_Routinen.ics');toast('Routinen exportiert. Bitte im Kalender importieren.')}
function showShield(mode='normal',isFocus=false){ui.shield={mode,isFocus};ui.breathLeft=3;drawShield();if(mode==='normal'){clearInterval(intervalTimer);intervalTimer=setInterval(()=>{if(!ui.shield||ui.shield.mode!=='normal'){clearInterval(intervalTimer);return}if(ui.breathLeft>0){ui.breathLeft--;drawShield()}else clearInterval(intervalTimer)},1000)}}
function drawShield(){let mode=ui.shield?.mode;if(!mode)return;let routine=mode==='morning'?'morning':'evening',checks=state.routineChecks[today]?.[routine]||[],tasks=state.routines[routine];let cfg=state.shieldContents[mode]||{goals:true},goals=cfg.goals?`<div style="margin:19px 0 16px">${state.goals.map(g=>`<div class="goal-line">${esc(g)}</div>`).join('')}</div>`:'';let extras=`${cfg.reminders&&todayEvents().length?`<div class="card-note"><div class="eyebrow">Heute</div>${todayEvents().map(e=>`<div style="margin-top:7px">${esc(e.time||'')} · ${esc(e.title)}</div>`).join('')}</div>`:''}${cfg.steps?`<div class="card-note"><div class="eyebrow">Schritte heute</div><strong>${state.steps[today]===undefined?'Noch nicht aktualisiert':Number(state.steps[today]).toLocaleString('de-DE')}</strong></div>`:''}${cfg.quote&&state.settings.quote?`<div class="card-note">${esc(state.settings.quote)}</div>`:''}${cfg.video&&state.video?`<button class="quiet-button" style="margin-top:10px" data-action="playVideo">${icon('play')} Video abspielen</button>`:''}`;let content=mode==='normal'?`<div class="eyebrow">Kurze Pause</div><h1 class="shield-title">Deine Richtung.</h1>${goals}${extras}<div class="breath-orb" style="width:105px;height:105px;margin:18px auto"><span style="font-size:28px;font-weight:720">${ui.breathLeft?ui.breathLeft:'✓'}</span></div><p class="muted">${ui.breathLeft?'Atme drei Sekunden langsam aus.':'Du kannst bewusst weitermachen.'}</p><button class="btn" data-action="shieldContinue" ${ui.breathLeft?'disabled':''}>${ui.shield.isFocus?'Fokuszeit beginnen':'Zur Übersicht'}</button>`:`<div class="eyebrow">${mode==='morning'?'Morgenroutine':'Abendroutine'}</div><h1 class="shield-title">${mode==='morning'?'Deine Ziele für heute.':'Dein Abschluss für heute.'}</h1>${goals}${extras}<div class="card-note"><div class="eyebrow">${mode==='morning'?'Morgen':'Abend'} · ${esc(state.settings[mode])}</div>${tasks.map((task,i)=>`<label class="checkrow"><input class="check" type="checkbox" data-shieldcheck="${i}" ${checks.includes(i)?'checked':''}><span>${esc(task)}</span></label>`).join('')}</div><button class="btn" data-action="shieldDone" ${checks.length<tasks.length?'disabled':''}>Routine abschließen</button>`;
let host=$('#modalHost');host.innerHTML=`<div class="full-shield"><button class="close-shield" data-action="shieldClose" aria-label="Vorschau schließen">${icon('close')}</button><div class="shield-inner">${featherArt(66)}${content}</div></div>`}
function closeShield(){clearInterval(intervalTimer);ui.shield=null;closeModal()}
function endFocus(){if(!ui.activeFocus)return;let minutes=Math.max(1,Math.ceil((Date.now()-ui.activeFocus.start)/60000));state.focusLog[today]=(state.focusLog[today]||0)+minutes;streakActive();ui.activeFocus=null;save();closeShield();render();toast(`${minutes} Minuten Fokuszeit gespeichert.`)}
function startFocusRun(){closeShield();ui.activeFocus={start:Date.now(),duration:ui.focusMinutes};drawActiveFocus()}
function drawActiveFocus(){if(!ui.activeFocus)return;let passed=Math.floor((Date.now()-ui.activeFocus.start)/60000),remaining=Math.max(0,ui.activeFocus.duration-passed);$('#modalHost').innerHTML=`<div class="full-shield"><div class="shield-inner">${featherArt(70)}<div class="eyebrow" style="margin-top:18px">Fokus läuft</div><h1 class="shield-title">Bei deiner Sache bleiben.</h1><div class="progress-big" style="margin:35px 0 8px">${remaining} min</div><p class="muted">${passed} Minuten seit Beginn · Ziel ${ui.activeFocus.duration} Minuten</p><button class="btn ghost" style="margin-top:28px" data-action="endFocus">Fokus beenden und Zeit speichern</button></div></div>`;clearInterval(intervalTimer);intervalTimer=setInterval(()=>{if(!ui.activeFocus){clearInterval(intervalTimer);return}let r=Math.max(0,ui.activeFocus.duration-Math.floor((Date.now()-ui.activeFocus.start)/60000));let el=$('.full-shield .progress-big');if(el)el.textContent=r+' min';if(r===0){clearInterval(intervalTimer);toast('Deine Fokuszeit ist erreicht.')}},10000)}
function backup(){download('KLAR_Backup_'+today+'.json',JSON.stringify({klarBackupVersion:1,created:new Date().toISOString(),data:state},null,2),'application/json');toast('Datensicherung heruntergeladen.')}
function restore(){openModal('Datensicherung importieren',`<p>Achtung: Die bisherigen Einträge werden durch die importierte Sicherung ersetzt.</p><label class="field"><span>KLAR-JSON-Datei auswählen</span><input id="backupFile" type="file" accept="application/json,.json"></label><button class="btn" data-action="restoreConfirm">Sicherung importieren</button>`)}
function launchShortcut(){window.location.href='shortcuts://run-shortcut?name=KLAR%20Schritte';toast('Falls der Kurzbefehl nicht existiert, bitte zuerst in Kurzbefehle anlegen.')}
function openShortcuts(){window.location.href='shortcuts://create-shortcut'}
async function pasteSteps(){try{let text=await navigator.clipboard.readText();let cleaned=text.replace(/[.\s]/g,'').replace(/,/g,'');let n=Number(cleaned);if(!/^\d+$/.test(cleaned)||!Number.isFinite(n)||n>200000){toast('In der Zwischenablage steht keine gültige Schrittzahl.');return}state.steps[today]=n;save();closeModal();render();toast('Heutige Schritte gespeichert.')}catch(e){toast('Zwischenablage nicht freigegeben. Nutze das Eingabefeld.')}}
async function share(){let payload={title:'KLAR',text:'Meine persönliche KLAR-App',url:location.protocol.startsWith('http')?location.href.split('?')[0]:''};try{if(navigator.share)await navigator.share(payload);else{await navigator.clipboard.writeText(payload.url);toast('Link kopiert.')}}catch(e){if(e.name!=='AbortError')toast('Teilen ist hier nicht möglich.')}}
function mainActions(e){let button=e.target.closest('[data-action]');if(button){let action=button.dataset.action,id=button.dataset.id;switch(action){case 'profile':openProfile();break;case 'rewards':ui.tab='progress';render();break;case 'settings':settingsModal();break;case 'share':share();break;case 'goals':goalsModal();break;case 'prevGoal':ui.goalIndex=(ui.goalIndex+state.goals.length-1)%state.goals.length;render();break;case 'nextGoal':ui.goalIndex=(ui.goalIndex+1)%state.goals.length;render();break;case 'removeGoal':if(state.goals.length>1){state.goals.pop();ui.goalIndex=0;save();goalsModal()}else toast('Mindestens ein Ziel bleibt.');break;case 'addEvent':eventModal();break;case 'eventActions':eventActions(id);break;case 'deleteEvent':state.events=state.events.filter(x=>x.id!==id);save();closeModal();render();toast('Eintrag entfernt.');break;case 'exportIcs':exportEvent(id);break;case 'video':videoModal();break;case 'playVideo':playVideo();break;case 'removeVideo':state.video='';save();closeModal();render();break;case 'routines':routinesModal();break;case 'previewRoutine':showShield(ui.routine);break;case 'editWorkout':workoutModal();break;case 'addExercise':workoutModal(true);break;case 'stepImport':stepModal();break;case 'pasteSteps':pasteSteps();break;case 'launchHealthShortcut':launchShortcut();break;case 'addWater':state.water[ui.selectedDate]=(state.water[ui.selectedDate]||0)+state.waterGlass;save();render();toast('Wasser hinzugefügt.');break;case 'waterSettings':settingsModal();break;case 'datePick':showCalendar();break;case 'calPrev':ui.calDate.setMonth(ui.calDate.getMonth()-1);showCalendar();showCalendar();break;case 'calNext':ui.calDate.setMonth(ui.calDate.getMonth()+1);showCalendar();showCalendar();break;case 'shortcuts':shortcutsModal();break;case 'openShortcuts':openShortcuts();break;case 'exportRoutines':exportRoutines();break;case 'exportPause':exportPauses('normal');break;case 'exportBlink':exportPauses('blink');break;case 'showShield':showShield(ui.focusMode);break;case 'startFocus':showShield('normal',true);break;case 'shieldContinue':if(ui.breathLeft<=0){if(ui.shield?.isFocus)startFocusRun();else{closeShield();render()}}break;case 'shieldClose':closeShield();break;case 'shieldDone':{let m=ui.shield.mode,arr=state.routineChecks[today]?.[m]||[];if(arr.length>=state.routines[m].length){streakActive();closeShield();render();toast('Routine abgeschlossen.')}break}case 'endFocus':endFocus();break;case 'closeModal':closeModal();break;case 'backup':backup();break;case 'restore':restore();break;case 'restoreConfirm':{let file=$('#backupFile')?.files[0];if(!file){toast('Bitte eine JSON-Datei wählen.');break}file.text().then(t=>{try{let json=JSON.parse(t);if(json.klarBackupVersion!==1||!json.data||!Array.isArray(json.data.goals))throw Error('Ungültig');localStorage.setItem('klar_private_v1',JSON.stringify(json.data));state=load();ui.goalIndex=0;closeModal();render();toast('Datensicherung importiert.')}catch(_){toast('Diese Datei ist keine gültige KLAR-Sicherung.')}});break}case 'aboutPrivacy':aboutPrivacy();break;case 'calToday':ui.selectedDate=today;ui.calDate=dt(today);render();break;default:break}return}
let tab=e.target.closest('[data-tab]');if(tab){ui.tab=tab.dataset.tab;render();window.scrollTo({top:0,behavior:'smooth'});return}
let routine=e.target.closest('[data-routine]');if(routine){ui.routine=routine.dataset.routine;render();return}
let day=e.target.closest('[data-day]');if(day){ui.planDay=Number(day.dataset.day);let chosen=new Date();chosen.setDate(chosen.getDate()+ui.planDay-(chosen.getDay()+6)%7);ui.selectedDate=dateKey(chosen);render();return}
let focus=e.target.closest('[data-focusmode]');if(focus){ui.focusMode=focus.dataset.focusmode;render();return}
let date=e.target.closest('[data-date]');if(date){ui.selectedDate=date.dataset.date;ui.calDate=dt(ui.selectedDate);render();return}}
function handleForm(e){let f=e.target;if(!(f instanceof HTMLFormElement))return;e.preventDefault();let d=new FormData(f);switch(f.id){case 'goalsForm':{let goals=state.goals.map((_,i)=>(d.get('goal'+i)||'').trim()).filter(Boolean),newGoal=(d.get('newGoal')||'').trim();if(newGoal)goals.push(newGoal);if(!goals.length){toast('Bitte mindestens ein Ziel eingeben.');return}state.goals=goals.slice(0,10);ui.goalIndex=0;break}case 'eventForm':state.events.push({id:uid(),title:String(d.get('title')||'').trim(),type:String(d.get('type')),date:String(d.get('date')),time:String(d.get('time')),note:String(d.get('note')||'').trim()});break;case 'videoForm':{let url=String(d.get('url')||'').trim();if(url&&!parseVideoURL(url)){toast('Bitte einen gültigen http(s)-Videolink eingeben.');return}state.video=url;state.videoTitle=String(d.get('title')||'Mein Video').trim();break}case 'routinesForm':state.routines.morning=String(d.get('morning')||'').split('\n').map(x=>x.trim()).filter(Boolean).slice(0,15);state.routines.evening=String(d.get('evening')||'').split('\n').map(x=>x.trim()).filter(Boolean).slice(0,15);state.settings.morning=String(d.get('morningTime'));state.settings.evening=String(d.get('eveningTime'));state.routineChecks[today]={};break;case 'workoutForm':{let w=state.workouts[ui.planDay];w.title=String(d.get('title'));w.note=String(d.get('note'));w.ex=String(d.get('ex')||'').split('\n').map(x=>x.split('|').map(s=>s.trim())).filter(x=>x[0]).map(([name,sets='',reps=''])=>({name,sets,reps}));break}case 'exerciseForm':state.workouts[ui.planDay].ex.push({name:String(d.get('name')).trim(),sets:String(d.get('sets')).trim(),reps:String(d.get('reps')).trim()});break;case 'stepsForm':{let n=Number(d.get('steps'));if(!Number.isFinite(n)||n<0||n>200000)return;state.steps[ui.selectedDate]=n;break}case 'settingsForm':state.name=String(d.get('name')||'').trim();state.stepGoal=Math.max(100,Math.min(50000,Number(d.get('stepGoal')||10000)));state.waterGlass=Math.max(50,Math.min(1000,Number(d.get('waterGlass')||250)));state.settings.appName=String(d.get('appName')||'TikTok');state.settings.appMinutes=Math.max(1,Math.min(120,Number(d.get('appMinutes')||10)));state.settings.normalInterval=Number(d.get('normalInterval'));state.settings.blink=Number(d.get('blink'));state.settings.quote=String(d.get('quote')||'').trim();for(const mode of ['morning','evening','normal']){state.shieldContents[mode]={};for(const k of ['goals','reminders','steps','video','quote'])state.shieldContents[mode][k]=d.has('shield_'+mode+'_'+k)}break;default:return}save();closeModal();render();toast('Gespeichert.')}
function handleChange(e){let r=e.target.closest('[data-routinecheck]');if(r){let i=Number(r.dataset.routinecheck),checks=state.routineChecks[today]||{morning:[],evening:[]};checks[ui.routine]=checks[ui.routine]||[];if(r.checked&&!checks[ui.routine].includes(i))checks[ui.routine].push(i);if(!r.checked)checks[ui.routine]=checks[ui.routine].filter(x=>x!==i);state.routineChecks[today]=checks;if(state.routines[ui.routine].length&&checks[ui.routine].length===state.routines[ui.routine].length)streakActive();save();render();return}
let sh=e.target.closest('[data-shieldcheck]');if(sh){let i=Number(sh.dataset.shieldcheck),mode=ui.shield?.mode;if(!mode||mode==='normal')return;state.routineChecks[today]=state.routineChecks[today]||{};let checks=state.routineChecks[today][mode]||[];if(sh.checked&&!checks.includes(i))checks.push(i);if(!sh.checked)checks=checks.filter(x=>x!==i);state.routineChecks[today][mode]=checks;save();drawShield();return}}
function handleInput(e){if(e.target.id==='focusDuration'){ui.focusMinutes=Number(e.target.value);$('#focusLabel').textContent=ui.focusMinutes+' Minuten'}}
function install(){document.addEventListener('click',mainActions);document.addEventListener('submit',handleForm);document.addEventListener('change',handleChange);document.addEventListener('input',handleInput);$('#dateButton').addEventListener('click',showCalendar);document.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()});if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});const params=new URL(location.href).searchParams;if(params.has('steps')){let n=Number(params.get('steps'));if(Number.isInteger(n)&&n>=0&&n<=200000){state.steps[today]=n;save();history.replaceState(null,'',location.pathname);toast('Schritte aus URL übernommen.')}}render();}
install();
